// deadline form: tokio::time::timeout(Duration::from_secs(2), call()).await?

let cancelled = Arc::new(AtomicBool::new(false));
let flag = Arc::clone(&cancelled);

let worker = thread::spawn(move || {
    while !flag.load(Ordering::Acquire) {        // safe point
        if let Some(job) = queue.pop_timeout(Duration::from_millis(100)) {
            run(job);
        }
    }
});
cancelled.store(true, Ordering::Release);        // request

